import { describe, expect, it } from "vitest";
import { periodReturn, quadrantOf, rotationPath, sectorStats } from "./sectors";
import type { PricePoint } from "@/lib/types/stock";

/** `n` consecutive daily closes ending 2026-10-23, generated by `price(i)`. */
function series(n: number, price: (i: number) => number): PricePoint[] {
  const end = Date.UTC(2026, 9, 23);
  return Array.from({ length: n }, (_, i) => ({
    date: new Date(end - (n - 1 - i) * 86_400_000).toISOString(),
    close: price(i),
  }));
}

describe("periodReturn", () => {
  it("measures back the given number of sessions", () => {
    const points = series(30, (i) => 100 + i); // last = 129
    expect(periodReturn(points, "1D")).toBeCloseTo(129 / 128 - 1);
    expect(periodReturn(points, "1W")).toBeCloseTo(129 / 124 - 1);
    expect(periodReturn(points, "1M")).toBeCloseTo(129 / 108 - 1);
  });

  it("anchors YTD to the last close of the previous year", () => {
    const points = series(400, (i) => 100 + i);
    const lastOf2025 = points.findLast((p) => p.date.startsWith("2025"))!;
    expect(periodReturn(points, "YTD")).toBeCloseTo(points.at(-1)!.close / lastOf2025.close - 1);
  });

  it("returns null when history is shorter than the period", () => {
    expect(periodReturn(series(30, () => 100), "1Y")).toBeNull();
    expect(periodReturn([], "1D")).toBeNull();
  });
});

describe("rotation", () => {
  const benchmark = series(300, () => 100);

  it("puts a sector pulling ahead at an accelerating pace in Leading", () => {
    const sector = series(300, (i) => 100 * 1.0005 ** (i * i / 100));
    const path = rotationPath(sector, benchmark);
    expect(path).toHaveLength(8);
    expect(quadrantOf(path.at(-1))).toBe("leading");
  });

  it("puts a sector falling behind at an accelerating pace in Lagging", () => {
    const sector = series(300, (i) => 100 * 0.9995 ** (i * i / 100));
    expect(quadrantOf(rotationPath(sector, benchmark).at(-1))).toBe("lagging");
  });

  it("puts a strong sector that has started to fade in Weakening", () => {
    // Climbs for most of the year, then gives a little back over two weeks.
    const sector = series(300, (i) => (i < 290 ? 100 + i : 390 - (i - 290) * 0.5));
    expect(quadrantOf(rotationPath(sector, benchmark).at(-1))).toBe("weakening");
  });

  it("ignores days the benchmark did not trade", () => {
    const sector = series(300, (i) => 100 + i);
    const gappy = benchmark.filter((_, i) => i % 7 !== 3);
    expect(() => rotationPath(sector, gappy)).not.toThrow();
    expect(rotationPath(sector, gappy).length).toBeGreaterThan(0);
  });
});

describe("sectorStats", () => {
  it("reports returns relative to the benchmark and the moving-average trend", () => {
    const benchmark = series(300, (i) => 100 + i * 0.1);
    const sector = series(300, (i) => 100 + i * 0.5);
    const stats = sectorStats({ symbol: "XLK", name: "Technology" }, sector, benchmark);

    expect(stats.price).toBeCloseTo(249.5);
    expect(stats.relative["1M"]).toBeCloseTo(stats.returns["1M"]! - periodReturn(benchmark, "1M")!);
    expect(stats.relative["1M"]!).toBeGreaterThan(0);
    expect(stats.aboveSma50).toBe(true);
    expect(stats.aboveSma200).toBe(true);
  });

  it("leaves the 200-day trend unknown with too little history", () => {
    const short = series(120, () => 100);
    expect(sectorStats({ symbol: "XLK", name: "Technology" }, short, short).aboveSma200).toBeNull();
  });
});
